it('rolls back Inventory, file binding, Quality, receipt and audit after a late outbox failure, then retries and replays the same command',async()=>{
 const created=await hold(),id=String(created.id);await inspectQualityHold(f.reviewer,id,qualityInspectionSchema.parse({expectedVersion:1,result:'fail',evidence:'Independent inspection confirms damaged packaging'}),key());
 const files=await seedAttachmentSet(db,f.manager,{targetType:'quality_hold',targetId:id,purposeKey:'disposition_evidence',componentRef:'disposition',expectedTargetVersion:2}),command=key(),countId=`quality-scrap-${command}`,fault=`quality_scrap_fault_${key().replaceAll('-','')}`,input={expectedVersion:2,dispositionDate:'2026-09-02',quantity:'1',reason:'Dispose of independently failed stock with supporting evidence',attachmentSetIds:[files.setId]};
 await db.exec(`CREATE FUNCTION ${fault}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'QUALITY_SCRAP_LATE_OUTBOX' USING ERRCODE='23514';END;$$;CREATE TRIGGER ${fault} AFTER INSERT ON outbox_events FOR EACH ROW WHEN(NEW.command_id='${command.replaceAll("'","''")}') EXECUTE FUNCTION ${fault}();`);
 try{await expect(createQualityScrapDisposition(f.manager,id,input,command)).rejects.toThrow();}finally{await db.exec(`DROP TRIGGER ${fault} ON outbox_events;DROP FUNCTION ${fault}();`);}
 expect(await getQualityHold(f.owner,id)).toMatchObject({status:'held',version:2,disposition_count_id:null});
 expect(await db.prepare('SELECT COUNT(*)::int count FROM inventory_counts WHERE id=?').bind(countId).first()).toEqual({count:0});
 expect(await db.prepare('SELECT COUNT(*)::int count FROM inventory_count_lines WHERE count_id=?').bind(countId).first()).toEqual({count:0});
 expect(await db.prepare('SELECT COUNT(*)::int count FROM inventory_quality_disposition_events WHERE count_id=?').bind(countId).first()).toEqual({count:0});
 expect(await attachmentBindingState(db,files.setId)).toMatchObject({set_state:'draft',link_state:'draft'});
 for(const table of ['command_receipts','audit_events','outbox_events'])expect(await db.prepare(`SELECT COUNT(*)::int count FROM ${table} WHERE command_id=?`).bind(command).first()).toEqual({count:0});
 const saved=await createQualityScrapDisposition(f.manager,id,input,command);expect(saved).toMatchObject({id,countId,status:'disposition_pending',version:3});expect(await createQualityScrapDisposition(f.manager,id,input,command)).toEqual(saved);
 expect(await attachmentBindingState(db,files.setId)).toMatchObject({set_state:'bound',link_state:'bound',binding_id:countId});
 expect(await db.prepare('SELECT COUNT(*)::int count FROM inventory_counts WHERE id=?').bind(countId).first()).toEqual({count:1});
});
it('rejects quality evidence staged for another inspection or disposition without changing the hold',async()=>{
 const created=await hold(),id=String(created.id);
 const wrongInspection=await seedAttachmentSet(db,f.reviewer,{targetType:'quality_hold',targetId:id,purposeKey:'quality_inspection_evidence',componentRef:'another-inspection',expectedTargetVersion:1});
 await expect(inspectQualityHold(f.reviewer,id,qualityInspectionSchema.parse({expectedVersion:1,result:'fail',evidence:'Wrong inspection context must be rejected',attachmentSetIds:[wrongInspection.setId]}),key())).rejects.toMatchObject({code:'ATTACHMENT_BINDING_CONTEXT'});
 expect(await attachmentBindingState(db,wrongInspection.setId)).toMatchObject({set_state:'draft',link_state:'draft'});
 expect(await db.prepare('SELECT status,version FROM inventory_quality_holds WHERE id=?').bind(id).first()).toEqual({status:'held',version:1});
 await inspectQualityHold(f.reviewer,id,qualityInspectionSchema.parse({expectedVersion:1,result:'fail',evidence:'Independent inspection confirms damage'}),key());
 const wrongDisposition=await seedAttachmentSet(db,f.manager,{targetType:'quality_hold',targetId:id,purposeKey:'disposition_evidence',componentRef:'another-disposition',expectedTargetVersion:2});
 await expect(createQualityScrapDisposition(f.manager,id,{expectedVersion:2,dispositionDate:'2026-09-02',quantity:'1',reason:'Wrong disposition context must be rejected',attachmentSetIds:[wrongDisposition.setId]},key())).rejects.toMatchObject({code:'ATTACHMENT_BINDING_CONTEXT'});
 expect(await attachmentBindingState(db,wrongDisposition.setId)).toMatchObject({set_state:'draft',link_state:'draft'});
 expect(await db.prepare('SELECT status,version,disposition_count_id FROM inventory_quality_holds WHERE id=?').bind(id).first()).toEqual({status:'held',version:2,disposition_count_id:null});
});
it('binds a canonical compatibility upload inside the Quality command while the UI gate is off',async()=>{
 const created=await hold(),id=String(created.id),files=await seedAttachmentSet(db,f.reviewer,{targetType:'quality_hold',targetId:id,purposeKey:'quality_inspection_evidence',componentRef:'inspection',expectedTargetVersion:1,compatibilityAdapter:true}),previous=process.env.ERPX_ATTACHMENTS_V2,previousReadOnly=process.env.ERPX_ATTACHMENTS_READ_ONLY,previousFreeze=process.env.ERPX_ATTACHMENT_UPLOAD_FREEZE,input={expectedVersion:1,result:'fail' as const,evidence:'Compatibility upload reviewed inside the inspection transaction',attachmentSetIds:[files.setId]};
 process.env.ERPX_ATTACHMENTS_V2='false';
 try{
  process.env.ERPX_ATTACHMENTS_READ_ONLY='true';await expect(inspectQualityHold(f.reviewer,id,qualityInspectionSchema.parse(input),key())).rejects.toMatchObject({code:'ATTACHMENTS_READ_ONLY'});delete process.env.ERPX_ATTACHMENTS_READ_ONLY;
  process.env.ERPX_ATTACHMENT_UPLOAD_FREEZE='true';await expect(inspectQualityHold(f.reviewer,id,qualityInspectionSchema.parse(input),key())).rejects.toMatchObject({code:'ATTACHMENT_UPLOAD_FREEZE'});delete process.env.ERPX_ATTACHMENT_UPLOAD_FREEZE;
  const command=key();await inspectQualityHold(f.reviewer,id,qualityInspectionSchema.parse(input),command);expect(await attachmentBindingState(db,files.setId)).toMatchObject({set_state:'bound',link_state:'bound',binding_type:'quality_inspection',binding_id:`inspection-${command}`});
 }finally{
  if(previous===undefined)delete process.env.ERPX_ATTACHMENTS_V2;else process.env.ERPX_ATTACHMENTS_V2=previous;
  if(previousReadOnly===undefined)delete process.env.ERPX_ATTACHMENTS_READ_ONLY;else process.env.ERPX_ATTACHMENTS_READ_ONLY=previousReadOnly;
  if(previousFreeze===undefined)delete process.env.ERPX_ATTACHMENT_UPLOAD_FREEZE;else process.env.ERPX_ATTACHMENT_UPLOAD_FREEZE=previousFreeze;
 }
});
