it('blocks already reserved Sales delivery atomically until all overlapping holds are released',async()=>{const created=await saveOrder(f.owner,null,orderSchema.parse({kind:'sales',partyId:party,warehouseId:warehouse,orderDate:'2026-09-02',dueDate:'2026-09-03',lines:[{productId:product,quantity:'2',price:'10',taxBps:0}]}),key()),id=String(created.id);await transitionOrder(f.owner,id,{action:'submit',expectedVersion:1},key());await transitionOrder(f.head,id,{action:'approve',expectedVersion:2},key());const source=await getOrder(f.owner,id),lineId=String(source.lines[0].id);await changeOrderReservation(f.owner,id,{expectedVersion:3,action:'reserve',lineId,quantity:'2',expiresAt:Date.now()+3600000,reason:'Customer delivery promise'},key());const a=await hold(),b=await hold(),proof=await deliveryEvidence(db,f.owner,id);const deliver=()=>fulfillOrder(f.owner,id,fulfillmentSchema.parse({expectedVersion:4,date:'2026-09-02',lines:[{lineId,quantity:'2'}],...proof}),key());await expect(deliver()).rejects.toThrow('QUALITY_HOLD');expect((await getOrder(f.owner,id)).lines[0].reserved_milli).toBe(2000);expect((await getOrder(f.owner,id)).order.version).toBe(4);for(const h of [a,b]){await inspectQualityHold(f.reviewer,String(h.id),qualityInspectionSchema.parse({expectedVersion:1,result:'pass',evidence:'Inspected contents and traceability'}),key());await releaseQualityHold(f.manager,String(h.id),{expectedVersion:2,reason:'Independent release review complete'},key());if(h===a)await expect(deliver()).rejects.toThrow('QUALITY_HOLD');}await deliver();expect(await db.prepare('SELECT quantity_milli,value_minor FROM commerce_stock WHERE warehouse_id=? AND product_id=?').bind(warehouse,product).first()).toEqual({quantity_milli:0,value_minor:0});});
