it.each(['disabled','enforced'] as const)('buffers original Quality hold aliases and controlled specification bytes with final full native policy (%s)',async mode=>{
 const {attachmentContent,bindRecordAttachmentSet}=await import('../../../src/server/modules/files/public/attachments/service');await purchaseQuality('supply');await purchaseQuality('supply-quality');vi.stubEnv('ERPX_COMMERCE_PACKAGE_ENFORCEMENT',mode);
 const one=String((await hold()).id),two=String((await hold()).id),spec=String((await saveQualitySpec(f.owner,null,{productId:product,name:'Original draft controlled Quality evidence',metrics:[{code:'weight',label:'Native weight',unit:'kg',minimum:'1',maximum:'3'}]},key())).id);
 for(const target of [{type:'quality_hold',id:one,purpose:'quality_inspection_evidence',actor:f.reviewer,componentKind:'action' as const},{type:'inventory_quality_hold',id:two,purpose:'inspection_evidence',actor:f.reviewer,componentKind:'action' as const},{type:'inventory_quality_spec',id:spec,purpose:'controlled_specification',actor:f.owner,componentKind:'record' as const}]){
  const document=await seedAttachmentSet(db,target.actor,{targetType:target.type,targetId:target.id,purposeKey:target.purpose,componentKind:target.componentKind,componentRef:target.componentKind==='action'?'inspection':undefined,expectedTargetVersion:1});if(target.componentKind==='record')await bindRecordAttachmentSet(db,target.actor,document.setId,1,key());
  const objectKey=String(await db.prepare('SELECT object_key FROM attachments WHERE id=?').bind(document.sourceId).first('object_key')),bytes=`Original exact Quality ${target.type}`;await env.H001_FILES.put(objectKey,bytes);let consumed=0;
  const files:FileStore={put:(...args)=>env.H001_FILES.put(...args),get:async(...args)=>{const object=await env.H001_FILES.get(...args);return object?{...object,arrayBuffer:async()=>{consumed++;return object.arrayBuffer();}}:null;},head:(...args)=>env.H001_FILES.head(...args),delete:(...args)=>env.H001_FILES.delete(...args),list:(...args)=>env.H001_FILES.list(...args)};
  for(const effect of [target.componentKind==='record'?`UPDATE inventory_quality_spec_metrics SET label='Late metric source' WHERE spec_id='${spec}'`:`UPDATE inventory_quality_holds SET reason='Late original source' WHERE id='${target.id}'`,`UPDATE attachments SET legal_hold=1 WHERE id='${document.sourceId}'`,`UPDATE assignments SET revoked_at=1,version=version+1 WHERE id='${target.actor.assignmentId}'`]){
   const fault=`quality_private_${key().replaceAll('-','')}`;await db.exec(`CREATE FUNCTION ${fault}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN ${effect};RETURN NEW;END $$;CREATE CONSTRAINT TRIGGER ${fault} AFTER INSERT ON attachment_access_events DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(NEW.link_id='${document.linkId}' AND NEW.outcome='allowed') EXECUTE FUNCTION ${fault}()`);
   try{await expect(attachmentContent(db,files,target.actor,document.linkId,'original')).rejects.toMatchObject({code:'QUALITY_FILE_READ_CHANGED'});}finally{await db.exec(`DROP TRIGGER ${fault} ON attachment_access_events;DROP FUNCTION ${fault}()`);}
   expect(await db.prepare("SELECT count(*)::int n FROM attachment_access_events WHERE link_id=? AND outcome='allowed'").bind(document.linkId).first('n')).toBe(0);
  }
  expect(consumed).toBe(3);await db.prepare('UPDATE attachments SET legal_hold=1 WHERE id=?').bind(document.sourceId).run();expect(await(await attachmentContent(db,files,target.actor,document.linkId,'original')).object.text()).toBe(bytes);expect(consumed).toBe(4);await expect(db.transaction(tx=>attachmentContent(tx,files,target.actor,document.linkId,'original'))).rejects.toMatchObject({code:'QUALITY_FILE_READ_TRANSACTION_REQUIRED'});expect(consumed).toBe(4);
 }
});
