 await expect(attachmentContent(db,env.H001_FILES,f.reviewer,document.linkId,'original')).rejects.toMatchObject({status:404});const before=Number(await db.prepare("SELECT count(*) n FROM attachment_access_events WHERE link_id=? AND outcome='denied'").bind(document.linkId).first('n'));expect(before).toBe(2);
 const fault=`quality_denied_${key().replaceAll('-','')}`;await db.exec(`CREATE FUNCTION ${fault}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE assignments SET version=version+1 WHERE id='${f.reviewer.assignmentId}';RETURN NEW;END $$;CREATE CONSTRAINT TRIGGER ${fault} AFTER INSERT ON attachment_access_events DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(NEW.link_id='${document.linkId}' AND NEW.outcome='denied') EXECUTE FUNCTION ${fault}()`);try{await expect(attachmentContent(db,env.H001_FILES,f.reviewer,document.linkId,'original')).rejects.toMatchObject({code:'QUALITY_FILE_READ_CHANGED'});}finally{await db.exec(`DROP TRIGGER ${fault} ON attachment_access_events;DROP FUNCTION ${fault}()`);}expect(Number(await db.prepare("SELECT count(*) n FROM attachment_access_events WHERE link_id=? AND outcome='denied'").bind(document.linkId).first('n'))).toBe(before);
