it('waits for actual independent Quality inspection before its fresh byte snapshot and avoids two Company source-write upgrade retries',async()=>{
 const {attachmentContent,bindRecordAttachmentSet}=await import('../../../src/server/modules/files/public/attachments/service'),{committedSourceVisibility}=await import('../../support/helpers/source-writer-visibility'),{measureReads}=await import('../../../src/server/modules/runtime/public/runtime/read-metrics');vi.stubEnv('ERPX_COMMERCE_PACKAGE_ENFORCEMENT','disabled');const id=String((await hold()).id),document=await seedAttachmentSet(db,f.reviewer,{targetType:'quality_hold',targetId:id,purposeKey:'quality_inspection_evidence',componentRef:'inspection',expectedTargetVersion:1}),objectKey=String(await db.prepare('SELECT object_key FROM attachments WHERE id=?').bind(document.sourceId).first('object_key'));await env.H001_FILES.put(objectKey,'Original retained independently inspected evidence');const fault=`quality_committed_${key().replaceAll('-','')}`;
 await db.exec(`CREATE FUNCTION ${fault}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF(SELECT version FROM inventory_quality_holds WHERE id='${id}')<>2 THEN RAISE EXCEPTION 'STALE_NATIVE_QUALITY_FILE_SOURCE';END IF;RETURN NEW;END $$;CREATE CONSTRAINT TRIGGER ${fault} AFTER INSERT ON attachment_access_events DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(NEW.link_id='${document.linkId}' AND NEW.outcome='allowed') EXECUTE FUNCTION ${fault}()`);
 try{const observed=await committedSourceVisibility(db,async tx=>{qualityDatabase=tx;try{await inspectQualityHold(f.reviewer,id,qualityInspectionSchema.parse({expectedVersion:1,result:'pass',evidence:'Actual independent native inspector commits before private byte source snapshot'}),key());}finally{qualityDatabase=undefined;}},()=>measureReads(()=>attachmentContent(db,env.H001_FILES,f.reviewer,document.linkId,'original')));expect(await observed.result.object.text()).toBe('Original retained independently inspected evidence');expect(observed.metrics.deadlockFailures??0).toBe(0);expect(observed.metrics.serializationFailures??0).toBe(0);expect(observed.metrics.transactionRetries??0).toBe(0);}finally{qualityDatabase=undefined;await db.exec(`DROP TRIGGER ${fault} ON attachment_access_events;DROP FUNCTION ${fault}()`);}
 const other=await expenseFixture(),otherProduct=String((await saveMaster(other.owner,'products',null,{sku:key(),name:'Other Company native Quality specification',price:'10'},key())).id),rows:{actor:WorkContext;product:string;spec:string;file:Awaited<ReturnType<typeof seedAttachmentSet>>;bytes:string}[]=[];
 for(const source of [{actor:f.owner,product},{actor:other.owner,product:otherProduct}]){const spec=String((await saveQualitySpec(source.actor,null,{productId:source.product,name:'Actual Company private Quality source',metrics:[{code:'weight',label:'Controlled native weight',unit:'kg',minimum:'1',maximum:'3'}]},key())).id),file=await seedAttachmentSet(db,source.actor,{targetType:'inventory_quality_spec',targetId:spec,componentKind:'record',purposeKey:'controlled_specification',expectedTargetVersion:1});await bindRecordAttachmentSet(db,source.actor,file.setId,1,key());const objectKey=String(await db.prepare('SELECT object_key FROM attachments WHERE id=?').bind(file.sourceId).first('object_key')),bytes=`Native Quality Company ${source.actor.companyId}`;await env.H001_FILES.put(objectKey,bytes);rows.push({...source,spec,file,bytes});}
 const parallel=`quality_parallel_${key().replaceAll('-','')}`;await db.exec(`CREATE FUNCTION ${parallel}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM pg_sleep(0.08);UPDATE inventory_quality_specs SET name=name WHERE id=CASE WHEN NEW.company_id='${f.company}' THEN '${rows[0].spec}' ELSE '${rows[1].spec}' END;RETURN NEW;END $$;CREATE CONSTRAINT TRIGGER ${parallel} AFTER INSERT ON attachment_access_events DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(NEW.link_id IN('${rows[0].file.linkId}','${rows[1].file.linkId}') AND NEW.outcome='allowed') EXECUTE FUNCTION ${parallel}()`);
 try{const observed=await measureReads(()=>Promise.all(rows.map(row=>attachmentContent(db,env.H001_FILES,row.actor,row.file.linkId,'original'))));for(let index=0;index<rows.length;index++)expect(await observed.result[index].object.text()).toBe(rows[index].bytes);expect(observed.metrics.deadlockFailures??0).toBe(0);expect(observed.metrics.serializationFailures??0).toBe(0);expect(observed.metrics.transactionRetries??0).toBe(0);}finally{await db.exec(`DROP TRIGGER ${parallel} ON attachment_access_events;DROP FUNCTION ${parallel}()`);}
});

